def parse_nested_parens(paren_string: str) -> List[int]:
    """ This utility function analyzes a string with multiple groups of nested parentheses, each group separated by a space.
    It computes the deepest nesting level for each group.
    For example, the group '(()())' has a maximum nesting level of 2, while '((()))' has a level of 3.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    groups = paren_string.split()
    result = []
    for group in groups:
        max_level = 0
        current_level = 0
        for char in group:
            if char == '(':
                current_level += 1
                max_level = max(max_level, current_level)
            elif char == ')':
                current_level -= 1
        result.append(max_level)
